#include "resident/domains/military/military_model.hpp"
// 舟战接触消耗同一半日计划轨迹；失能静止船仍可成为实际接舷目标，但不制造移动预算。
#include "naval_contact.hpp"
#include "battle_world.hpp"
#include "naval_manifest_history.hpp"
#include "naval_repair.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident {
namespace {
// 只从当前唯一军旅/实船账读实际对象。
template<class T>const T* find(const std::vector<T>& rows,const StableId& id){for(const auto& row:rows)if(row.id==id)return &row;return nullptr;}
bool has(const std::vector<StableId>& rows,const StableId& id){return std::find(rows.begin(),rows.end(),id)!=rows.end();}
// 船在碰面整数锚点仍须合法浮航；不能套用原陆军静止点的army模式。
bool anchors_legal(const TravelCatalog& geography,const TravelServices& services,const ContactHit& hit){for(const auto* endpoint:{&hit.first,&hit.second}){const auto* map=geography.maps.find(endpoint->anchor.map_id);if(!map||!terrain::point_valid_prepared(*map,endpoint->anchor.point,terrain::Mode::boat,services.terrain_flags()))return false;if(!endpoint->trace.stationary&&(endpoint->trace.params.mode!="boat"||endpoint->trace.params.points.empty()||!terrain::segment_cost_prepared(*map,endpoint->anchor.point,endpoint->trace.params.points.front(),terrain::Mode::boat,{}).ok))return false;}return true;}
}
// 全量源校验由World准入负责，本次再核船只占用/载荷/实际Action与征讨权源。
static Outcome<NavalContactProbe> probe_naval_contacts_impl(const CommonRead& common,const MilitaryState& military,const MilitaryCatalog& commands,const MilitaryAccess& access,const NavalAssetState& assets,const NavalAssetCatalog& ships,const TravelState& travel,const TravelCatalog& geography,const TravelServices& services,const std::vector<NavalContactHistory>& history,const std::vector<StableId>& occupied,const std::vector<StableId>& held,bool combat_enabled,const std::function<Outcome<NavalFormationQuote>(const NavalFleetRecord&)>& check_manifest,const std::function<Outcome<std::optional<NavalTravelProof>>(const StableId&)>& travel_proof,const std::function<bool(const NavalFleetRecord&)>& repairing){
 NavalContactProbe result;if(ships.world_map_id!=geography.world_map_id||!geography.maps.find(ships.world_map_id))return {false,{},common_failure("NavalWaterMapRequired").error};auto checked=validate_naval_assets(assets,ships,combat_enabled);if(!checked.ok)return {false,{},checked.error};
 struct Eligible {const NavalFleetRecord* fleet;const ArmyRecord* army;TravelMotion motion;};std::vector<Eligible> eligible;std::vector<const NavalFleetRecord*> fleets;for(const auto& fleet:assets.fleets)if(fleet.status=="active")fleets.push_back(&fleet);std::sort(fleets.begin(),fleets.end(),[](auto a,auto b){return a->id<b->id;});std::set<StableId> commanders;
 for(const auto* fleet:fleets){if(has(occupied,fleet->id)||has(held,fleet->commander_actor_id))continue;const auto* army=find(military.armies,fleet->army_id);const auto* person=common.actor(fleet->commander_actor_id);if(!army||army->status!="active"||army->commander_actor_id!=fleet->commander_actor_id||!person)return {false,{},common_failure("NavalContactSourceUnavailable",fleet->id).error};if(!person->alive||!person->available)continue;if(military_actor_in_battle(military,person->id))return {false,{},common_failure("NavalLandOccupationOverlap",fleet->id).error};
  auto manifest=check_manifest(*fleet);if(!manifest.ok)return {false,{},manifest.error};if(!commanders.insert(person->id).second)return {false,{},common_failure("NavalCommanderAssignedTwice",person->id).error};std::optional<TravelMotion> motion;
  if(person->action_id.empty()||(repairing&&repairing(*fleet))){if(const auto* at=std::get_if<WildernessLocation>(&person->location))motion=stationary_terrain_trace(person->id,*at);}
  else{const auto* action=common.action(person->action_id);if(!action||action->kind!="travel"||action->actor_id!=person->id)continue;const auto* params=travel.actions.find(action->id);if(!params||params->mode!="boat")return {false,{},common_failure("NavalTravelActionMismatch",person->id).error};auto proof=travel_proof(person->id);if(!proof.ok)return {false,{},proof.error};if(!proof.value||proof.value->fleet_id!=fleet->id)return {false,{},common_failure("NavalFleetProofRequired",fleet->id).error};auto trace=terrain_motion(common,geography,services,*action,*params,held);if(!trace.ok){if(trace.error.kind!=ErrorKind::rule)return {false,{},trace.error};continue;}motion=std::move(trace.value);}
  if(motion&&motion->map_id==ships.world_map_id&&validate_terrain_trace(*motion).ok)eligible.push_back({fleet,army,std::move(*motion)});
 }
 result.eligible_fleets=eligible.size();ContactEntrances entrances;for(const auto& settlement:geography.settlements.rows())entrances[geography.world_map_id].push_back(settlement.second.map_xy);std::vector<NavalContactHit> hits;
 for(std::size_t i=0;i<eligible.size();++i)for(std::size_t j=i+1;j<eligible.size();++j){const auto& a=eligible[i];const auto& b=eligible[j];++result.candidate_pairs;if(!military_armies_hostile(military,commands,*a.army,*b.army))continue;
  bool prior=false;if(a.motion.stationary||b.motion.stationary){const auto& moving=a.motion.stationary?b:a;const auto& still=a.motion.stationary?a:b;for(const auto& fact:history){if(fact.first_fleet_id==still.fleet->id&&fact.second_fleet_id==moving.fleet->id&&fact.second_motion.action_id==moving.motion.action_id&&!moving.motion.action_id.empty())prior=true;if(fact.second_fleet_id==still.fleet->id&&fact.first_fleet_id==moving.fleet->id&&fact.first_motion.action_id==moving.motion.action_id&&!moving.motion.action_id.empty())prior=true;}}if(prior)continue;
  ++result.exact_pairs;auto crossed=terrain_intersection(a.motion,b.motion,entrances);if(!crossed||!anchors_legal(geography,services,*crossed))continue;const auto& first=crossed->a==a.motion.actor_id?a:b;const auto& second=crossed->b==b.motion.actor_id?b:a;NavalContactHit hit;hit.first_fleet_id=first.fleet->id;hit.second_fleet_id=second.fleet->id;hit.contact.source_tick=common.tick();hit.contact.first_army_id=first.army->id;hit.contact.second_army_id=second.army->id;hit.contact.first_motion=first.motion;hit.contact.second_motion=second.motion;hit.contact.contact=std::move(*crossed);hits.push_back(std::move(hit));
 }
 std::sort(hits.begin(),hits.end(),[](const auto& a,const auto& b){return contact_before(a.contact.contact,b.contact.contact);});std::set<StableId> used;for(auto& hit:hits){if(used.count(hit.first_fleet_id)||used.count(hit.second_fleet_id))continue;used.insert(hit.first_fleet_id);used.insert(hit.second_fleet_id);result.ordered_hits.push_back(std::move(hit));}return {true,std::move(result),{}};
}
// 资产1调用保旧形状和原军旅载荷合同，不因编译进舟战而自动升级profile。
Outcome<NavalContactProbe> probe_naval_contacts(const CommonRead& c,const MilitaryState& m,const MilitaryCatalog& mc,const MilitaryAccess& a,const NavalAssetState& n,const NavalAssetCatalog& nc,const TravelState& t,const TravelCatalog& tc,const TravelServices& ts,const std::vector<NavalContactHistory>& history,const std::vector<StableId>& occupied,const std::vector<StableId>& held){return probe_naval_contacts_impl(c,m,mc,a,n,nc,t,tc,ts,history,occupied,held,false,[&](const auto& fleet){return validate_naval_manifest(c,m,n,nc,fleet);},[&](const auto& actor){return preview_naval_travel(c,m,mc,a,n,nc,actor);},{});}
// 显式战斗2使用已验证捕获历史的投影，几何顺序/Travel半日仍完全复用。
Outcome<NavalContactProbe> probe_naval_contacts(const CommonRead& c,const MilitaryState& m,const MilitaryCatalog& mc,const MilitaryAccess& a,const NavalState& n,const NavalCatalog& nc,const TravelState& t,const TravelCatalog& tc,const TravelServices& ts,const std::vector<NavalContactHistory>& history,const std::vector<StableId>& occupied,const std::vector<StableId>& held){if(!nc.combat_policy)return {false,{},common_failure("NavalCombatProfileRequired").error};return probe_naval_contacts_impl(c,m,mc,a,n,nc,t,tc,ts,history,occupied,held,true,[&](const auto& fleet){return validate_naval_combat_manifest(c,m,n,nc,fleet);},[&](const auto& actor){return preview_naval_combat_travel(c,m,mc,a,n,nc,actor);},[&](const auto& fleet){return active_naval_repair(c,n,nc,fleet.id)!=nullptr;});}

}
